package main

import (
	"context"
	"fmt"
	"time"

	"go.mongodb.org/mongo-driver/bson"
	"go.mongodb.org/mongo-driver/mongo"
	"go.mongodb.org/mongo-driver/mongo/options"
)

type RankedEmployee struct {
	Name       string   `bson:"name"`
	Department string   `bson:"department"`
	Salary     float64  `bson:"salary"`
	Rank       int      `bson:"salary_rank"`
	DiffPrev   *float64 `bson:"diff_from_previous"`
}

func main() {
	ctx, cancel := context.WithTimeout(context.Background(), 5*time.Second)
	defer cancel()

	client, err := mongo.Connect(ctx, options.Client().ApplyURI("mongodb://localhost:27017"))
	if err != nil {
		panic(err)
	}
	defer client.Disconnect(ctx)

	coll := client.Database("hr").Collection("salaries")
	_ = coll.Drop(ctx)

	_, _ = coll.InsertMany(ctx, []interface{}{
		bson.M{"name": "Иван", "department": "IT", "salary": 300000.0},
		bson.M{"name": "Мария", "department": "IT", "salary": 300000.0},
		bson.M{"name": "Петр", "department": "IT", "salary": 250000.0},
		bson.M{"name": "Анна", "department": "Sales", "salary": 180000.0},
		bson.M{"name": "Егор", "department": "Sales", "salary": 140000.0},
	})

	// Стадия $setWindowFields
	pipeline := mongo.Pipeline{
		{{Key: "$setWindowFields", Value: bson.D{
			{Key: "partitionBy", Value: "$department"},
			{Key: "sortBy", Value: bson.D{{Key: "salary", Value: -1}}},
			{Key: "output", Value: bson.D{
				{Key: "salary_rank", Value: bson.D{{Key: "$denseRank", Value: bson.D{}}}},
				{Key: "prev_salary", Value: bson.D{{Key: "$shift", Value: bson.D{
					{Key: "output", Value: "$salary"},
					{Key: "by", Value: -1}, // Предыдущий документ в окне
				}}}},
			}},
		}}},
		// Вычисляем разницу с предыдущей зарплатой
		{{Key: "$addFields", Value: bson.D{
			{Key: "diff_from_previous", Value: bson.D{
				{Key: "$subtract", Value: bson.A{"$salary", "$prev_salary"}},
			}},
		}}},
	}

	cur, err := coll.Aggregate(ctx, pipeline)
	if err != nil {
		panic(err)
	}
	defer cur.Close(ctx)

	var results []RankedEmployee
	_ = cur.All(ctx, &results)

	fmt.Println("Аналитический рейтинг зарплат по отделам ($setWindowFields):")
	for _, e := range results {
		diffStr := "N/A (топ отдела)"
		if e.DiffPrev != nil {
			diffStr = fmt.Sprintf("%.2f руб.", *e.DiffPrev)
		}
		fmt.Printf("  Отдел: %-5s | Ранг: %d | %-6s (%.0f руб.) | Разница с лидером: %s\n",
			e.Department, e.Rank, e.Name, e.Salary, diffStr)
	}
}

package main

import (
	"context"
	"fmt"
	"time"

	"go.mongodb.org/mongo-driver/bson"
	"go.mongodb.org/mongo-driver/mongo"
	"go.mongodb.org/mongo-driver/mongo/options"
	"go.mongodb.org/mongo-driver/mongo/readconcern"
	"go.mongodb.org/mongo-driver/mongo/writeconcern"
)

type Account struct {
	ID      string  `bson:"_id"`
	Owner   string  `bson:"owner"`
	Balance float64 `bson:"balance"`
}

func TransferMoney(ctx context.Context, client *mongo.Client, fromID, toID string, amount float64) error {
	session, err := client.StartSession()
	if err != nil {
		return fmt.Errorf("ошибка старта сессии: %w", err)
	}
	defer session.EndSession(ctx)

	txnOpts := options.Transaction().
		SetReadConcern(readconcern.Snapshot()).
		SetWriteConcern(writeconcern.Majority())

	_, err = session.WithTransaction(ctx, func(sessCtx mongo.SessionContext) (interface{}, error) {
		coll := client.Database("banking").Collection("accounts")

		// 1. Списание со счета отправителя с условием достаточного баланса
		resFrom, err := coll.UpdateOne(sessCtx,
			bson.M{"_id": fromID, "balance": bson.M{"$gte": amount}},
			bson.M{"$inc": bson.M{"balance": -amount}},
		)
		if err != nil {
			return nil, err
		}
		if resFrom.MatchedCount == 0 {
			// Возврат ошибки вызовет автоматический AbortTransaction
			return nil, fmt.Errorf("недостаточно средств на счете %s или счет не существует", fromID)
		}

		// 2. Зачисление на счет получателя
		resTo, err := coll.UpdateOne(sessCtx,
			bson.M{"_id": toID},
			bson.M{"$inc": bson.M{"balance": amount}},
		)
		if err != nil {
			return nil, err
		}
		if resTo.MatchedCount == 0 {
			return nil, fmt.Errorf("счет получателя %s не найден", toID)
		}

		return nil, nil
	}, txnOpts)

	return err
}

func main() {
	ctx, cancel := context.WithTimeout(context.Background(), 10*time.Second)
	defer cancel()

	client, err := mongo.Connect(ctx, options.Client().ApplyURI("mongodb://localhost:27017/?replicaSet=rs0"))
	if err != nil {
		panic(err)
	}
	defer client.Disconnect(ctx)

	coll := client.Database("banking").Collection("accounts")
	_ = coll.Drop(ctx)

	_, _ = coll.InsertMany(ctx, []interface{}{
		Account{ID: "ACC-1", Owner: "Иван", Balance: 500.0},
		Account{ID: "ACC-2", Owner: "Мария", Balance: 100.0},
	})

	fmt.Println("Перевод 250 руб с ACC-1 на ACC-2:")
	if err := TransferMoney(ctx, client, "ACC-1", "ACC-2", 250.0); err != nil {
		fmt.Printf("Ошибка: %v\n", err)
	} else {
		fmt.Println("Транзакция успешно зафиксирована!")
	}

	var a1, a2 Account
	_ = coll.FindOne(ctx, bson.M{"_id": "ACC-1"}).Decode(&a1)
	_ = coll.FindOne(ctx, bson.M{"_id": "ACC-2"}).Decode(&a2)
	fmt.Printf("Итог: Иван=%.2f руб., Мария=%.2f руб.\n", a1.Balance, a2.Balance)
}

package main

import (
	"context"
